const cfg = {
  locationId: 'Zwz4relUXVPxx8uohnjV',
  apiBaseUrl: 'https://services.leadconnectorhq.com',
  apiKey: 'pit-a55a45b3-f933-4898-9cbb-7cfe74c95d28',
};

const requiredFields = [
  { name: 'Company Phone', dataType: 'TEXT' },
];

const baseUrl = cfg.apiBaseUrl.replace(/\/$/, '');
const headers = {
  Authorization: `Bearer ${cfg.apiKey}`,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}

async function apiRequest({ method, path, body }) {
  const options = {
    method,
    url: `${baseUrl}${path}`,
    headers,
    json: true,
  };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, status: 200, data };
  } catch (err) {
    return {
      ok: false,
      status: err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500,
      data: err?.response?.body || err?.message || err,
      requestBody: body,
    };
  }
}

function getArrayPayload(obj) {
  if (Array.isArray(obj)) return obj;
  if (Array.isArray(obj?.customFields)) return obj.customFields;
  if (Array.isArray(obj?.data?.customFields)) return obj.data.customFields;
  if (Array.isArray(obj?.data)) return obj.data;
  return [];
}

const listRes = await apiRequest.call(this, { method: 'GET', path: `/locations/${cfg.locationId}/customFields?model=contact` });
if (!listRes.ok) {
  throw new Error(`Failed to fetch custom fields: ${listRes.status} ${JSON.stringify(listRes.data)}`);
}

const existing = getArrayPayload(listRes.data);
const byName = new Map(existing.map((f) => [String(f?.name || '').trim(), f]));

const results = [];
for (const field of requiredFields) {
  const found = byName.get(field.name);
  if (found) {
    results.push({ fieldName: field.name, fieldId: found.id || null, action: 'Reused', dataType: found.dataType || null });
    continue;
  }

  const candidateBodies = [
    { name: field.name, model: 'contact', dataType: field.dataType },
    { name: field.name, objectKey: 'contact', dataType: field.dataType },
  ];

  let created = null;
  let lastErr = null;
  for (const body of candidateBodies) {
    const cr = await apiRequest.call(this, { method: 'POST', path: `/locations/${cfg.locationId}/customFields`, body });
    if (cr.ok) {
      created = cr.data;
      break;
    }
    lastErr = cr;
  }

  if (!created) {
    throw new Error(`Failed creating ${field.name}: ${JSON.stringify(lastErr)}`);
  }

  results.push({
    fieldName: field.name,
    fieldId: created?.id || created?.customField?.id || created?.data?.id || null,
    action: 'Created',
    dataType: field.dataType,
  });
}

return [{ json: { ok: true, locationId: cfg.locationId, fields: results } }];
